        elif isinstance(value, str) and (
            hinted_args is int or hinted_args is float
        ):
            try:
                payload[arg] = hinted_args(value)
            except ValueError:
                raise ValueError(
                    f"Received a string value ({value}) for {arg} but expected a {hinted_args}"
